using Entities.Enemies.Helpers;
using Entities.Enemies.Render;
using Entities.Players.Data;
using GameItems.Cards;
using TMPro;

namespace Entities.Enemies.Manager
{
    using System.Collections.Generic;
    using UnityEngine;

    public class EnemyManager : MonoBehaviour
    {
        [Header("Data")]
        public List<EnemyData> enemies = new();

        [Header("Intent Icons")]
        [Tooltip("Reference to the global card icon library for enemy intents.")]
        public CardIconLibrary iconLibrary;

        [Header("Rendering")]
        [Tooltip("Parent container where enemy GameObjects (SpriteRenderer + Animator) will be spawned in world space.")]
        public Transform uiContainer; // now a Transform, not a RectTransform
        [Tooltip("Prefab for the enemy health bar UI (must have EnemyHealth component).")]
        [SerializeField] private GameObject healthBarPrefab;
        [Tooltip("Prefab for the enemy rendering (must have EnemyRender component with child UI elements).")]
        [SerializeField] private EnemyRender enemyPrefab;

        [Header("Layout (Line-up)")]
        [Tooltip("Horizontal spacing between enemies in world units.")]
        [SerializeField] private float horizontalSpacing = 2f;
        [Tooltip("Fixed Y offset for the line-up (local to container).")]
        [SerializeField] private float yOffset;
        [Tooltip("Center the lineup around X=0. If false, lineup starts at X=0 and grows positive.")]
        [SerializeField] private bool centerAlign = true;
        [Tooltip("Automatically layout enemies after (re)building.")]
        [SerializeField] private bool autoLayoutOnBuild = true;

        [Header("Health Bar Settings")]
        [Tooltip("Local position offset for health bar relative to enemy.")]
        [SerializeField] private Vector3 healthBarOffset = new Vector3(0f, 0.17f, 0f);

        [Header("Enemy Render Settings")]
        [Tooltip("Sprite to show when any enemy is hovered over by the player.")]
        public Sprite hoverSprite;

        [Tooltip("Y offset for hover sprite position relative to enemy.")]
        public float hoverSpriteYOffset;

        [Tooltip("Offset from enemy position where intent icon appears.")]
        public Vector3 intentIconOffset = new Vector3(0f, 0.23f, 0f);

        [Tooltip("Size of the intent icon sprite.")]
        public float intentIconSize = 0.2f;

        [Tooltip("Sorting order offset for hover sprite from enemy sprite.")]
        public int hoverSpriteSortingOrderOffset = 5;

        private readonly List<EnemyRender> _activeRenders = new();

        public void InitializeEnemies(List<EnemyData> enemyList)
        {
            enemies = enemyList;
            BuildEnemyUI();

            foreach (var e in enemies)
            {
                // track the enemy encounter in list
                TrackEnemyEncounter(e.sourceConfig);
            }
        }

        private void TrackEnemyEncounter(EnemyConfig config)
        {
            if (config == null) return;

            string flagName = $"monster.{config.enemyName.ToLower()}";

            if (!GameFlags.HasFlag(flagName))
            {
                GameFlags.SetFlag(flagName);
                Debug.Log($"[Flags] First encounter with {config.enemyName}. Set flag: {flagName}");
            }

            // If you prefer using unique IDs instead:
            // string flagName = $"monster.{config.uniqueID}";
        }

        private void BuildEnemyUI()
        {
            // Cleanup old
            foreach (var r in _activeRenders)
            {
                if (r != null) Destroy(r.gameObject);
            }
            _activeRenders.Clear();

            if (uiContainer == null)
            {
                Debug.LogWarning("EnemyManager: uiContainer not set. Enemies will not be rendered.");
                return;
            }

            if (enemyPrefab == null)
            {
                Debug.LogWarning("EnemyManager: enemyPrefab not set. Cannot spawn enemies.");
                return;
            }

            if (healthBarPrefab == null)
            {
                Debug.LogWarning("EnemyManager: healthBarPrefab not set. Health bars will not be created.");
            }

            for (int i = 0; i < enemies.Count; i++)
            {
                var enemy = enemies[i];

                // Instantiate from prefab
                var instance = Instantiate(enemyPrefab, uiContainer);
                var go = instance.gameObject;

                // Rename for clarity
                go.name = string.IsNullOrEmpty(enemy.enemyName) ? $"Enemy_{i}" : enemy.enemyName;

                // World-space transform defaults
                var t = go.transform;
                t.localPosition = Vector3.zero;
                t.localScale = Vector3.one * 10f;
                t.localRotation = Quaternion.identity;

                var sr = go.GetComponent<SpriteRenderer>();
                if (sr != null)
                {
                    sr.sprite = enemy.artwork;
                    sr.sortingOrder = i; // order by spawn index (front-to-back or vice versa as needed)
                }

                // Add health bar if prefab is available
                if (healthBarPrefab != null)
                {
                    var healthBarGo = Instantiate(healthBarPrefab, go.transform);
                    var healthComp = healthBarGo.GetComponent<EnemyHealth>();
                    if (healthComp != null)
                    {
                        healthComp.SetLocalPosition(healthBarOffset);
                        // Initial health will be set in EnemyRender.Bind
                    }
                    else
                    {
                        Debug.LogWarning($"EnemyManager: healthBarPrefab for {enemy.enemyName} does not have EnemyHealth component.");
                    }
                }

                // Bind the enemy data to the render component
                instance.Bind(enemy, hoverSprite, hoverSpriteYOffset, intentIconOffset, intentIconSize, hoverSpriteSortingOrderOffset);

                _activeRenders.Add(instance);
            }

            if (autoLayoutOnBuild)
                ApplyLineUpLayout();
        }

        private void ApplyLineUpLayout()
        {
            int count = _activeRenders.Count;
            if (count == 0) return;

            float startX = centerAlign ? -((count - 1) * horizontalSpacing) * 0.5f : 0f;

            for (int i = 0; i < count; i++)
            {
                var r = _activeRenders[i];
                if (r == null) continue;

                var t = r.transform;
                t.localPosition = new Vector3(startX + i * horizontalSpacing, yOffset, 0f);
            }
        }

        // Roll/decide next intents for all alive enemies (called at round start)
        public void RollNextIntents()
        {
            for (int i = 0; i < enemies.Count; i++)
            {
                var enemy = enemies[i];
                if (!enemy.isAlive) continue;

                // DON'T reset block here - let it persist through the player's turn

                enemy.DecideNextIntent();

                // Ensure idle is playing so player sees them idling before attack
                var r = GetRenderFor(enemy);
                if (r != null)
                {
                    r.PlayIdle();
                    r.UpdateIntentIcon(); // Show the intent icon
                    r.UpdateHealth(); // Keep existing block visible
                }
            }
        }


        public void RemoveDeadEnemies()
        {
            for (int i = enemies.Count - 1; i >= 0; i--)
            {
                if (!enemies[i].isAlive)
                {
                    enemies.RemoveAt(i);

                    if (_activeRenders.Count > i)
                        _activeRenders.RemoveAt(i);
                }
            }

            // re-layout remaining enemies
            // ApplyLineUpLayout();
        }

        // Enemies execute their previously decided intents with delays (turn-based feel)
        public System.Collections.IEnumerator ExecuteEnemyTurnSequence(PlayerData player)
        {

            for (int i = 0; i < enemies.Count; i++)
            {
                var enemy = enemies[i];
                if (!enemy.isAlive) continue;

                Debug.Log($"[EnemyManager] {enemy.enemyName} is taking their turn...");

                // Get the render for animation
                var r = GetRenderFor(enemy);

                // Show move name popup BEFORE executing the move
                if (r != null)
                {
                    // Use GetMoveNameForAction to support custom names
                    string moveName = r.GetMoveNameForAction(enemy.currentAction);

                    // Show popup and wait for it to be visible
                    r.ShowMoveNamePopup(moveName);
                    yield return new WaitForSeconds(0.3f); // Brief pause to let player see the move name
                }

                // Play intent animation based on type
                if (enemy.currentIntent == EnemyIntent.Attack)
                {
                    if (r != null) r.PlayAttack();

                    // Wait for attack animation to play out
                    yield return new WaitForSeconds(0.5f);
                }
                else if (enemy.currentIntent == EnemyIntent.Block)
                {
                    if (r != null) r.PlayIdle(); // Or a defend animation if you have one
                    yield return new WaitForSeconds(0.3f);
                }
                else
                {
                    // Default for Heal/Buff/other intents
                    if (r != null) r.PlayIdle();
                    yield return new WaitForSeconds(0.3f);
                }

                // Execute the intent (apply damage, gain block, etc.)
                enemy.ExecuteIntent(player);

                // Update the enemy's health display to show new shield/health values
                if (r != null)
                {
                    r.UpdateHealth();
                }

                // Brief pause to show the effect
                yield return new WaitForSeconds(0.4f);

                // Return to idle after action
                if (r != null) r.PlayIdle();

                // Delay before next enemy acts
                yield return new WaitForSeconds(0.6f);
            }

            Debug.Log("[EnemyManager] All enemies have completed their turns.");
        }

        // Legacy synchronous method - kept for backwards compatibility but deprecated
        [System.Obsolete("Use ExecuteEnemyTurnSequence coroutine instead for turn-based delays")]
        public void ExecuteEnemyTurn(ref PlayerData player)
        {
            for (int i = 0; i < enemies.Count; i++)
            {
                var enemy = enemies[i];
                if (!enemy.isAlive) continue;

                // Play attack animation right before executing if intent is attack
                if (enemy.currentIntent == EnemyIntent.Attack)
                {
                    var r = GetRenderFor(enemy);
                    if (r != null) r.PlayAttack();
                }

                enemy.ExecuteIntent(player);
            }
        }

        // Call after enemy takes damage to update health display
        public void UpdateEnemyHealth(EnemyData enemy)
        {
            var render = GetRenderFor(enemy);
            if (render != null)
            {
                render.UpdateHealth();

                // Play hurt animation if still alive
                if (enemy.isAlive)
                {
                    render.PlayHurt();
                }
                else
                {
                    render.PlayDeath();

                    RemoveDeadEnemies(); // remove from manager list
                }
            }
            FindFirstObjectByType<RoundManager>()?.CheckImmediateEndConditions();
        }

        // Age enemy block and reset old block (1+ turns old)
        // This allows block gained THIS turn to persist through the next round
        public void ResetAllEnemyBlock()
        {
            foreach (var enemy in enemies)
            {
                if (!enemy.isAlive) continue;

                // Increment block age
                if (enemy.block > 0)
                {
                    enemy.blockAge++;

                    // Only reset block that's 1 or more turns old
                    if (enemy.blockAge >= 2)
                    {
                        Debug.Log($"[EnemyManager] {enemy.enemyName} block expired (age {enemy.blockAge}): {enemy.block} → 0");
                        enemy.block = 0;
                        enemy.blockAge = 0;

                        var r = GetRenderFor(enemy);
                        if (r != null)
                            r.UpdateHealth();
                    }
                    else
                    {
                        Debug.Log($"[EnemyManager] {enemy.enemyName} block persists (age {enemy.blockAge}): {enemy.block} block");
                    }
                }
            }
        }

        private EnemyRender GetRenderFor(EnemyData enemy)
        {
            // Renders are built in the same order as enemies
            int idx = enemies.IndexOf(enemy);
            if (idx >= 0 && idx < _activeRenders.Count)
                return _activeRenders[idx];
            return null;
        }

        public bool AllEnemiesDefeated()
        {
            foreach (var e in enemies)
                if (e.isAlive) return false;
            return true;
        }

        /// <summary>
        /// Creates a new EnemyPrefab with all necessary child objects and components.
        /// Call this from the Editor or at runtime to generate the prefab structure.
        /// </summary>
        /// <param name="parentTransform">Optional: parent transform for the prefab. If null, creates at root.</param>
        /// <returns>The EnemyRender component of the created prefab.</returns>
        public static EnemyRender CreateEnemyPrefab(Transform parentTransform = null)
        {
            // Create root GameObject
            var rootGo = new GameObject("EnemyPrefab");
            rootGo.transform.SetParent(parentTransform, false);

            // Add required components to root
            var spriteRenderer = rootGo.AddComponent<SpriteRenderer>();
            spriteRenderer.sprite = null; // Will be set per enemy
            spriteRenderer.sortingOrder = 0;

            var boxCollider = rootGo.AddComponent<BoxCollider2D>();
            boxCollider.offset = new Vector2(0f, 0.05f);
            boxCollider.size = new Vector2(0.3f, 0.3f);

            rootGo.AddComponent<Animator>();
            // Note: Animator Controller will need to be assigned in Editor if needed

            var enemyRender = rootGo.AddComponent<EnemyRender>();

            // ========== Create IntentIcon child ==========
            var intentIconGo = new GameObject("IntentIcon");
            intentIconGo.transform.SetParent(rootGo.transform, false);
            intentIconGo.transform.localPosition = Vector3.zero;
            intentIconGo.transform.localScale = Vector3.one;

            var intentIconSr = intentIconGo.AddComponent<SpriteRenderer>();
            intentIconSr.sprite = null; // Will be set by UpdateIntentIcon
            intentIconSr.sortingOrder = 10;
            intentIconSr.enabled = false;

            // Create IntentValueText as child of IntentIcon
            var intentValueGo = new GameObject("IntentValueText");
            intentValueGo.transform.SetParent(intentIconGo.transform, false);
            intentValueGo.transform.localPosition = new Vector3(0.15f, -0.12f, 0f);

            var intentValueText = intentValueGo.AddComponent<TextMeshProUGUI>();
            intentValueText.text = "";
            intentValueText.alignment = TextAlignmentOptions.Center;
            intentValueText.fontSize = 2;
            intentValueText.color = Color.white;
            intentValueText.enabled = false;

            // ========== Create MoveNameText child ==========
            var moveNameGo = new GameObject("MoveNameText");
            moveNameGo.transform.SetParent(rootGo.transform, false);
            moveNameGo.transform.localPosition = new Vector3(0f, -0.11f, 0f);
            moveNameGo.transform.localScale = Vector3.one;

            var moveNameText = moveNameGo.AddComponent<TextMeshProUGUI>();
            moveNameText.text = "";
            moveNameText.alignment = TextAlignmentOptions.Center;
            moveNameText.fontSize = 2;
            moveNameText.color = Color.yellow;
            moveNameText.fontStyle = FontStyles.Bold;
            moveNameText.enabled = false;

            // ========== Create HoverSprite child ==========
            var hoverSpriteGo = new GameObject("HoverSprite");
            hoverSpriteGo.transform.SetParent(rootGo.transform, false);
            hoverSpriteGo.transform.localPosition = new Vector3(0f, 0f, 0f);
            hoverSpriteGo.transform.localScale = Vector3.one;

            var hoverSpriteSr = hoverSpriteGo.AddComponent<SpriteRenderer>();
            hoverSpriteSr.sprite = null; // Will be set by EnemyManager
            hoverSpriteSr.sortingOrder = 5;
            hoverSpriteSr.color = new Color32(251, 236, 93, 150); // Default yellowish
            hoverSpriteSr.enabled = false;

            // ========== Wire up EnemyRender references ==========
            // Use reflection or direct assignment to set the private fields
            var intentIconRootField = typeof(EnemyRender).GetField("intentIconRoot", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            var intentIconSpriteField = typeof(EnemyRender).GetField("intentIconSprite", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            var intentValueTextField = typeof(EnemyRender).GetField("intentValueText", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            var moveNameRootField = typeof(EnemyRender).GetField("moveNameRoot", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            var moveNameTextField = typeof(EnemyRender).GetField("moveNameText", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            var hoverSpriteRootField = typeof(EnemyRender).GetField("hoverSpriteRoot", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            var hoverSpriteRendererField = typeof(EnemyRender).GetField("hoverSpriteRenderer", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);

            if (intentIconRootField != null) intentIconRootField.SetValue(enemyRender, intentIconGo);
            if (intentIconSpriteField != null) intentIconSpriteField.SetValue(enemyRender, intentIconSr);
            if (intentValueTextField != null) intentValueTextField.SetValue(enemyRender, intentValueText);
            if (moveNameRootField != null) moveNameRootField.SetValue(enemyRender, moveNameGo);
            if (moveNameTextField != null) moveNameTextField.SetValue(enemyRender, moveNameText);
            if (hoverSpriteRootField != null) hoverSpriteRootField.SetValue(enemyRender, hoverSpriteGo);
            if (hoverSpriteRendererField != null) hoverSpriteRendererField.SetValue(enemyRender, hoverSpriteSr);

            Debug.Log("[EnemyManager] EnemyPrefab created successfully with all child objects and components.");

            return enemyRender;
        }
    }
}

using Entities.Enemies.Helpers;
using Entities.Enemies.Render;
using Entities.Players.Data;
using GameItems.Cards;
using TMPro;

namespace Entities.Enemies.Manager
{
    using System.Collections.Generic;
    using UnityEngine;

    public class EnemyManager : MonoBehaviour
    {
        [Header("Data")]
        public List<EnemyData> enemies = new();

        [Header("Intent Icons")]
        [Tooltip("Reference to the global card icon library for enemy intents.")]
        public CardIconLibrary iconLibrary;

        [Header("Rendering")]
        [Tooltip("Parent container where enemy GameObjects (SpriteRenderer + Animator) will be spawned in world space.")]
        public Transform uiContainer; // now a Transform, not a RectTransform
        [Tooltip("Prefab for the enemy health bar UI (must have EnemyHealth component).")]
        [SerializeField] private GameObject healthBarPrefab;
        [Tooltip("Prefab for the enemy rendering (must have EnemyRender component with child UI elements).")]
        [SerializeField] private EnemyRender enemyPrefab;

        [Header("Layout (Line-up)")]
        [Tooltip("Horizontal spacing between enemies in world units.")]
        [SerializeField] private float horizontalSpacing = 2f;
        [Tooltip("Fixed Y offset for the line-up (local to container).")]
        [SerializeField] private float yOffset;
        [Tooltip("Center the lineup around X=0. If false, lineup starts at X=0 and grows positive.")]
        [SerializeField] private bool centerAlign = true;
        [Tooltip("Automatically layout enemies after (re)building.")]
        [SerializeField] private bool autoLayoutOnBuild = true;

        [Header("Health Bar Settings")]
        [Tooltip("Local position offset for health bar relative to enemy.")]
        [SerializeField] private Vector3 healthBarOffset = new Vector3(0f, 0.17f, 0f);

        [Header("Enemy Render Settings")]
        [Tooltip("Sprite to show when any enemy is hovered over by the player.")]
        public Sprite hoverSprite;

        [Tooltip("Y offset for hover sprite position relative to enemy.")]
        public float hoverSpriteYOffset;

        [Tooltip("Offset from enemy position where intent icon appears.")]
        public Vector3 intentIconOffset = new Vector3(0f, 0.23f, 0f);

        [Tooltip("Size of the intent icon sprite.")]
        public float intentIconSize = 0.2f;

        [Tooltip("Sorting order offset for hover sprite from enemy sprite.")]
        public int hoverSpriteSortingOrderOffset = 5;

        private readonly List<EnemyRender> _activeRenders = new();

        public void InitializeEnemies(List<EnemyData> enemyList)
        {
            enemies = enemyList;
            BuildEnemyUI();

            foreach (var e in enemies)
            {
                // track the enemy encounter in list
                TrackEnemyEncounter(e.sourceConfig);
            }
        }

        private void TrackEnemyEncounter(EnemyConfig config)
        {
            if (config == null) return;

            string flagName = $"monster.{config.enemyName.ToLower()}";

            if (!GameFlags.HasFlag(flagName))
            {
                GameFlags.SetFlag(flagName);
                Debug.Log($"[Flags] First encounter with {config.enemyName}. Set flag: {flagName}");
            }

            // If you prefer using unique IDs instead:
            // string flagName = $"monster.{config.uniqueID}";
        }

        private void BuildEnemyUI()
        {
            // Cleanup old
            foreach (var r in _activeRenders)
            {
                if (r != null) Destroy(r.gameObject);
            }
            _activeRenders.Clear();

            if (uiContainer == null)
            {
                Debug.LogWarning("EnemyManager: uiContainer not set. Enemies will not be rendered.");
                return;
            }

            if (enemyPrefab == null)
            {
                Debug.LogWarning("EnemyManager: enemyPrefab not set. Cannot spawn enemies.");
                return;
            }

            if (healthBarPrefab == null)
            {
                Debug.LogWarning("EnemyManager: healthBarPrefab not set. Health bars will not be created.");
            }

            for (int i = 0; i < enemies.Count; i++)
            {
                var enemy = enemies[i];

                // Instantiate from prefab
                var instance = Instantiate(enemyPrefab, uiContainer);
                var go = instance.gameObject;

                // Rename for clarity
                go.name = string.IsNullOrEmpty(enemy.enemyName) ? $"Enemy_{i}" : enemy.enemyName;

                // World-space transform defaults
                var t = go.transform;
                t.localPosition = Vector3.zero;
                t.localScale = Vector3.one * 10f;
                t.localRotation = Quaternion.identity;

                var sr = go.GetComponent<SpriteRenderer>();
                if (sr != null)
                {
                    sr.sprite = enemy.artwork;
                    sr.sortingOrder = i; // order by spawn index (front-to-back or vice versa as needed)
                }

                // Add health bar if prefab is available
                if (healthBarPrefab != null)
                {
                    var healthBarGo = Instantiate(healthBarPrefab, go.transform);
                    var healthComp = healthBarGo.GetComponent<EnemyHealth>();
                    if (healthComp != null)
                    {
                        healthComp.SetLocalPosition(healthBarOffset);
                        // Initial health will be set in EnemyRender.Bind
                    }
                    else
                    {
                        Debug.LogWarning($"EnemyManager: healthBarPrefab for {enemy.enemyName} does not have EnemyHealth component.");
                    }
                }

                // Bind the enemy data to the render component
                instance.Bind(enemy, hoverSprite, hoverSpriteYOffset, intentIconOffset, intentIconSize, hoverSpriteSortingOrderOffset);

                _activeRenders.Add(instance);
            }

            if (autoLayoutOnBuild)
                ApplyLineUpLayout();
        }

        private void ApplyLineUpLayout()
        {
            int count = _activeRenders.Count;
            if (count == 0) return;

            float startX = centerAlign ? -((count - 1) * horizontalSpacing) * 0.5f : 0f;

            for (int i = 0; i < count; i++)
            {
                var r = _activeRenders[i];
                if (r == null) continue;

                var t = r.transform;
                t.localPosition = new Vector3(startX + i * horizontalSpacing, yOffset, 0f);
            }
        }

        // Roll/decide next intents for all alive enemies (called at round start)
        public void RollNextIntents()
        {
            for (int i = 0; i < enemies.Count; i++)
            {
                var enemy = enemies[i];
                if (!enemy.isAlive) continue;

                // DON'T reset block here - let it persist through the player's turn

                enemy.DecideNextIntent();

                // Ensure idle is playing so player sees them idling before attack
                var r = GetRenderFor(enemy);
                if (r != null)
                {
                    r.PlayIdle();
                    r.UpdateIntentIcon(); // Show the intent icon
                    r.UpdateHealth(); // Keep existing block visible
                }
            }
        }


        public void RemoveDeadEnemies()
        {
            for (int i = enemies.Count - 1; i >= 0; i--)
            {
                if (!enemies[i].isAlive)
                {
                    enemies.RemoveAt(i);

                    if (_activeRenders.Count > i)
                        _activeRenders.RemoveAt(i);
                }
            }

            // re-layout remaining enemies
            // ApplyLineUpLayout();
        }

        // Enemies execute their previously decided intents with delays (turn-based feel)
        public System.Collections.IEnumerator ExecuteEnemyTurnSequence(PlayerData player)
        {

            for (int i = 0; i < enemies.Count; i++)
            {
                var enemy = enemies[i];
                if (!enemy.isAlive) continue;

                Debug.Log($"[EnemyManager] {enemy.enemyName} is taking their turn...");

                // Get the render for animation
                var r = GetRenderFor(enemy);

                // Show move name popup BEFORE executing the move
                if (r != null)
                {
                    // Use GetMoveNameForAction to support custom names
                    string moveName = r.GetMoveNameForAction(enemy.currentAction);

                    // Show popup and wait for it to be visible
                    r.ShowMoveNamePopup(moveName);
                    yield return new WaitForSeconds(0.3f); // Brief pause to let player see the move name
                }

                // Play intent animation based on type
                if (enemy.currentIntent == EnemyIntent.Attack)
                {
                    if (r != null)
                    {
                        Debug.Log($"[EnemyManager] {enemy.enemyName} executing Attack. Playing attack animation.");
                        r.PlayAttack();
                    }

                    // Wait a bit for animation to start showing the attack
                    yield return new WaitForSeconds(0.2f);

                    // Now play the attack sound while animation is mid-swing
                    if (r != null)
                    {
                        Debug.Log($"[EnemyManager] {enemy.enemyName} - Playing attack sound now.");
                        r.PlayEnemyAttackSound();
                    }

                    // Wait for rest of attack animation to play out
                    yield return new WaitForSeconds(0.4f);
                }
                else if (enemy.currentIntent == EnemyIntent.Block)
                {
                    if (r != null)
                    {
                        Debug.Log($"[EnemyManager] {enemy.enemyName} executing Block. Playing idle animation.");
                        r.PlayIdle(); // Or a defend animation if you have one
                    }

                    // Wait a bit for visual setup
                    yield return new WaitForSeconds(0.15f);

                    // Play defense sound as block/shield effect happens
                    if (r != null)
                    {
                        Debug.Log($"[EnemyManager] {enemy.enemyName} - Playing defense sound now.");
                        r.PlayEnemyDefenseSound();
                    }

                    yield return new WaitForSeconds(0.2f);
                }
                else
                {
                    // Default for Heal/Buff/other intents
                    if (r != null) r.PlayIdle();
                    yield return new WaitForSeconds(0.3f);
                }

                // Execute the intent (apply damage, gain block, etc.)
                enemy.ExecuteIntent(player);

                // Update the enemy's health display to show new shield/health values
                if (r != null)
                {
                    r.UpdateHealth();
                }

                // Brief pause to show the effect
                yield return new WaitForSeconds(0.4f);

                // Return to idle after action
                if (r != null) r.PlayIdle();

                // Delay before next enemy acts
                yield return new WaitForSeconds(0.6f);
            }

            Debug.Log("[EnemyManager] All enemies have completed their turns.");
        }

        // Legacy synchronous method - kept for backwards compatibility but deprecated
        [System.Obsolete("Use ExecuteEnemyTurnSequence coroutine instead for turn-based delays")]
        public void ExecuteEnemyTurn(ref PlayerData player)
        {
            for (int i = 0; i < enemies.Count; i++)
            {
                var enemy = enemies[i];
                if (!enemy.isAlive) continue;

                // Play attack animation right before executing if intent is attack
                if (enemy.currentIntent == EnemyIntent.Attack)
                {
                    var r = GetRenderFor(enemy);
                    if (r != null) r.PlayAttack();
                }

                enemy.ExecuteIntent(player);
            }
        }

        // Call after enemy takes damage to update health display
        public void UpdateEnemyHealth(EnemyData enemy)
        {
            var render = GetRenderFor(enemy);
            if (render != null)
            {
                render.UpdateHealth();

                // Play hurt animation if still alive
                if (enemy.isAlive)
                {
                    render.PlayHurt();
                }
                else
                {
                    render.PlayDeath();

                    RemoveDeadEnemies(); // remove from manager list
                }
            }
            FindFirstObjectByType<RoundManager>()?.CheckImmediateEndConditions();
        }

        // Age enemy block and reset old block (1+ turns old)
        // This allows block gained THIS turn to persist through the next round
        public void ResetAllEnemyBlock()
        {
            foreach (var enemy in enemies)
            {
                if (!enemy.isAlive) continue;

                // Increment block age
                if (enemy.block > 0)
                {
                    enemy.blockAge++;

                    // Only reset block that's 1 or more turns old
                    if (enemy.blockAge >= 2)
                    {
                        Debug.Log($"[EnemyManager] {enemy.enemyName} block expired (age {enemy.blockAge}): {enemy.block} → 0");
                        enemy.block = 0;
                        enemy.blockAge = 0;

                        var r = GetRenderFor(enemy);
                        if (r != null)
                            r.UpdateHealth();
                    }
                    else
                    {
                        Debug.Log($"[EnemyManager] {enemy.enemyName} block persists (age {enemy.blockAge}): {enemy.block} block");
                    }
                }
            }
        }

        private EnemyRender GetRenderFor(EnemyData enemy)
        {
            // Renders are built in the same order as enemies
            int idx = enemies.IndexOf(enemy);
            if (idx >= 0 && idx < _activeRenders.Count)
                return _activeRenders[idx];
            return null;
        }

        public bool AllEnemiesDefeated()
        {
            foreach (var e in enemies)
                if (e.isAlive) return false;
            return true;
        }

        /// <summary>
        /// Creates a new EnemyPrefab with all necessary child objects and components.
        /// Call this from the Editor or at runtime to generate the prefab structure.
        /// </summary>
        /// <param name="parentTransform">Optional: parent transform for the prefab. If null, creates at root.</param>
        /// <returns>The EnemyRender component of the created prefab.</returns>
        public static EnemyRender CreateEnemyPrefab(Transform parentTransform = null)
        {
            // Create root GameObject
            var rootGo = new GameObject("EnemyPrefab");
            rootGo.transform.SetParent(parentTransform, false);

            // Add required components to root
            var spriteRenderer = rootGo.AddComponent<SpriteRenderer>();
            spriteRenderer.sprite = null; // Will be set per enemy
            spriteRenderer.sortingOrder = 0;

            var boxCollider = rootGo.AddComponent<BoxCollider2D>();
            boxCollider.offset = new Vector2(0f, 0.05f);
            boxCollider.size = new Vector2(0.3f, 0.3f);

            rootGo.AddComponent<Animator>();
            // Note: Animator Controller will need to be assigned in Editor if needed

            var enemyRender = rootGo.AddComponent<EnemyRender>();

            // ========== Create IntentIcon child ==========
            var intentIconGo = new GameObject("IntentIcon");
            intentIconGo.transform.SetParent(rootGo.transform, false);
            intentIconGo.transform.localPosition = Vector3.zero;
            intentIconGo.transform.localScale = Vector3.one;

            var intentIconSr = intentIconGo.AddComponent<SpriteRenderer>();
            intentIconSr.sprite = null; // Will be set by UpdateIntentIcon
            intentIconSr.sortingOrder = 10;
            intentIconSr.enabled = false;

            // Create IntentValueText as child of IntentIcon
            var intentValueGo = new GameObject("IntentValueText");
            intentValueGo.transform.SetParent(intentIconGo.transform, false);
            intentValueGo.transform.localPosition = new Vector3(0.15f, -0.12f, 0f);

            var intentValueText = intentValueGo.AddComponent<TextMeshProUGUI>();
            intentValueText.text = "";
            intentValueText.alignment = TextAlignmentOptions.Center;
            intentValueText.fontSize = 2;
            intentValueText.color = Color.white;
            intentValueText.enabled = false;

            // ========== Create MoveNameText child ==========
            var moveNameGo = new GameObject("MoveNameText");
            moveNameGo.transform.SetParent(rootGo.transform, false);
            moveNameGo.transform.localPosition = new Vector3(0f, -0.11f, 0f);
            moveNameGo.transform.localScale = Vector3.one;

            var moveNameText = moveNameGo.AddComponent<TextMeshProUGUI>();
            moveNameText.text = "";
            moveNameText.alignment = TextAlignmentOptions.Center;
            moveNameText.fontSize = 2;
            moveNameText.color = Color.yellow;
            moveNameText.fontStyle = FontStyles.Bold;
            moveNameText.enabled = false;

            // ========== Create HoverSprite child ==========
            var hoverSpriteGo = new GameObject("HoverSprite");
            hoverSpriteGo.transform.SetParent(rootGo.transform, false);
            hoverSpriteGo.transform.localPosition = new Vector3(0f, 0f, 0f);
            hoverSpriteGo.transform.localScale = Vector3.one;

            var hoverSpriteSr = hoverSpriteGo.AddComponent<SpriteRenderer>();
            hoverSpriteSr.sprite = null; // Will be set by EnemyManager
            hoverSpriteSr.sortingOrder = 5;
            hoverSpriteSr.color = new Color32(251, 236, 93, 150); // Default yellowish
            hoverSpriteSr.enabled = false;

            // ========== Wire up EnemyRender references ==========
            // Use reflection or direct assignment to set the private fields
            var intentIconRootField = typeof(EnemyRender).GetField("intentIconRoot", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            var intentIconSpriteField = typeof(EnemyRender).GetField("intentIconSprite", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            var intentValueTextField = typeof(EnemyRender).GetField("intentValueText", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            var moveNameRootField = typeof(EnemyRender).GetField("moveNameRoot", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            var moveNameTextField = typeof(EnemyRender).GetField("moveNameText", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            var hoverSpriteRootField = typeof(EnemyRender).GetField("hoverSpriteRoot", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            var hoverSpriteRendererField = typeof(EnemyRender).GetField("hoverSpriteRenderer", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);

            if (intentIconRootField != null) intentIconRootField.SetValue(enemyRender, intentIconGo);
            if (intentIconSpriteField != null) intentIconSpriteField.SetValue(enemyRender, intentIconSr);
            if (intentValueTextField != null) intentValueTextField.SetValue(enemyRender, intentValueText);
            if (moveNameRootField != null) moveNameRootField.SetValue(enemyRender, moveNameGo);
            if (moveNameTextField != null) moveNameTextField.SetValue(enemyRender, moveNameText);
            if (hoverSpriteRootField != null) hoverSpriteRootField.SetValue(enemyRender, hoverSpriteGo);
            if (hoverSpriteRendererField != null) hoverSpriteRendererField.SetValue(enemyRender, hoverSpriteSr);

            Debug.Log("[EnemyManager] EnemyPrefab created successfully with all child objects and components.");

            return enemyRender;
        }
    }
}

using Entities.Enemies.Helpers;
using UnityEngine;
using TMPro;
using DG.Tweening;
using GameItems.Cards;

namespace Entities.Enemies.Render
{
    [RequireComponent(typeof(Animator))]
    [RequireComponent(typeof(SpriteRenderer))]
    [RequireComponent(typeof(BoxCollider2D))]
    public class EnemyRender : MonoBehaviour
    {
        [Header("Runtime")] public EnemyData data;

        [Header("Intent Icon")]
        [Tooltip("Offset from enemy position where intent icon appears")]
        public Vector3 intentIconOffset = new Vector3(0f, 0.23f, 0f);
        [Tooltip("Size of the intent icon sprite")]
        public float intentIconSize = 0.2f;
        [Tooltip("Sorting layer for intent icon")]
        public string intentIconSortingLayer = "Default";
        [Tooltip("Sorting order offset from enemy sprite")]
        public int intentIconSortingOrderOffset = 10;

        [Header("Intent Value Text")]
        [Tooltip("Offset from icon where value text appears")]
        public Vector3 intentValueOffset = new(0.15f, -0.12f, 0f);
        [Tooltip("Font size for intent value")]
        public float intentValueFontSize = 2f;
        [Tooltip("Color for intent value text")]
        public Color intentValueColor = Color.white;

        [Header("Move Name Popup")]
        [Tooltip("Offset from enemy position where move name appears")]
        public Vector3 moveNameOffset = new(0f, -0.11f, 0f);
        [Tooltip("Font size for move name")]
        public float moveNameFontSize = 2f;
        [Tooltip("Color for move name text")]
        public Color moveNameColor = Color.yellow;
        [Tooltip("Duration of move name popup animation")]
        public float moveNameDuration = 1.5f;
        [Tooltip("How far the text moves up during animation")]
        public float moveNameFloatDistance = -0.04f;
        [Tooltip("Sound effect to play when move name appears")]
        public SFXCueData moveNameSoundCue;

        [Header("Hover Sprite")]
        [Tooltip("Sprite to show when enemy is hovered over")]
        public Sprite hoverSprite;
        [Tooltip("Y offset for hover sprite position")]
        public float hoverSpriteYOffset;
        [Tooltip("Sorting layer for hover sprite")]
        public string hoverSpriteSortingLayer = "Default";
        [Tooltip("Sorting order offset from enemy sprite")]
        public int hoverSpriteSortingOrderOffset = 5;

        [Header("Hover Sprite Animation")]
        [Tooltip("Maximum scale multiplier when hover sprite expands")]
        public float hoverSpriteMaxScale = 1.1f;
        [Tooltip("Duration of one pulse cycle (expand + contract)")]
        public float hoverSpritePulseDuration = 1f;

        [Header("Animator States (Controller-driven)")]
        public string idleState = "Idle";

        public string attackState = "Attack";
        public string hurtState = "Hurt";
        public string deathState = "Death";
        public int animatorLayer;
        public float crossFadeDuration = 0.08f;

        // References provided by EnemyPrefab hierarchy
        [Header("Prefab References")]
        [Tooltip("Root GameObject for the intent icon (child of EnemyPrefab)")]
        [SerializeField] private GameObject intentIconRoot;
        [Tooltip("SpriteRenderer used for the intent icon")] 
        [SerializeField] private SpriteRenderer intentIconSprite;
        [Tooltip("TextMeshPro component used for the intent value")] 
        [SerializeField] private TMP_Text intentValueText;
        [Tooltip("Root GameObject for the move name popup text")] 
        [SerializeField] private GameObject moveNameRoot;
        [Tooltip("TextMeshPro component used for the move name popup")] 
        [SerializeField] private TMP_Text moveNameText;
        [Tooltip("Root GameObject for the hover sprite")] 
        [SerializeField] private GameObject hoverSpriteRoot;
        [Tooltip("SpriteRenderer used for the hover overlay")] 
        [SerializeField] private SpriteRenderer hoverSpriteRenderer;

        private SpriteRenderer _sprite;
        private EnemyHealth _health;
        private BoxCollider2D _hitboxCollider;

        private Tween _hoverSpritePulseTween; // Tracks the pulse animation

        // Manual sprite animation state
        private SpriteAnimation _currentAnimation;
        private float _frameTimer;
        private int _currentFrame;
        private bool _isAnimationPlaying;

        private void Awake()
        {
            _hitboxCollider = GetComponent<BoxCollider2D>();
            _sprite = GetComponent<SpriteRenderer>();

            // Apply initial offsets/sizing to prefab children if they are assigned
            if (intentIconRoot != null)
            {
                intentIconRoot.transform.localPosition = intentIconOffset;
                intentIconRoot.transform.localScale = Vector3.one * intentIconSize;
            }
            if (intentIconSprite != null)
            {
                intentIconSprite.sortingLayerName = intentIconSortingLayer;
                intentIconSprite.sortingOrder = _sprite.sortingOrder + intentIconSortingOrderOffset;
                intentIconSprite.enabled = false;
            }
            if (intentValueText != null)
            {
                intentValueText.rectTransform.localPosition = intentValueOffset;
                intentValueText.fontSize = intentValueFontSize;
                intentValueText.color = intentValueColor;
                intentValueText.alignment = TextAlignmentOptions.Center;
                intentValueText.enabled = false;
            }

            if (moveNameRoot != null)
            {
                moveNameRoot.transform.localPosition = moveNameOffset;
            }
            if (moveNameText != null)
            {
                moveNameText.fontSize = moveNameFontSize;
                moveNameText.color = moveNameColor;
                moveNameText.alignment = TextAlignmentOptions.Center;
                moveNameText.fontStyle = FontStyles.Bold;
                moveNameText.enabled = false;
            }

            if (hoverSpriteRoot != null)
            {
                hoverSpriteRoot.transform.localPosition = new Vector3(0f, hoverSpriteYOffset, 0f);
            }
            if (hoverSpriteRenderer != null)
            {
                hoverSpriteRenderer.sortingLayerName = hoverSpriteSortingLayer;
                hoverSpriteRenderer.sortingOrder = _sprite.sortingOrder + hoverSpriteSortingOrderOffset;
                if (hoverSpriteRenderer.color.a == 0f)
                {
                    hoverSpriteRenderer.color = new Color32(251, 236, 93, 150);
                }
                hoverSpriteRenderer.enabled = false;
            }
        }

        private void Update()
        {
            if (!_isAnimationPlaying || _currentAnimation == null || _currentAnimation.frames.Count == 0)
                return;

            _frameTimer += Time.deltaTime;
            float frameDuration = 1f / _currentAnimation.frameRate;

            if (_frameTimer >= frameDuration)
            {
                _frameTimer -= frameDuration;
                _currentFrame++;

                if (_currentFrame >= _currentAnimation.frames.Count)
                {
                    if (_currentAnimation.loop)
                    {
                        _currentFrame = 0;
                    }
                    else
                    {
                        _isAnimationPlaying = false;
                        PlayIdle(); // Revert to idle when non-looping animation finishes
                        return;
                    }
                }

                _sprite.sprite = _currentAnimation.frames[_currentFrame];
            }
            data.worldPosition = transform.position;
        }


        public void Bind(EnemyData enemyData, Sprite hoverSpriteOverride = null, float? hoverSpriteYOffsetOverride = null, Vector3? intentIconOffsetOverride = null, float? intentIconSizeOverride = null, int? hoverSpriteSortingOrderOffsetOverride = null)
        {
            data = enemyData;
            data.worldPosition = transform.position;
            data.isPlayer = false;

            // Set default sprite artwork
            if (_sprite != null)
            {
                _sprite.sprite = data != null ? data.artwork : null;
                _sprite.enabled = _sprite.sprite != null;
            }

            // Apply visual adjustments from EnemyData
            if (data != null)
            {
                // Apply position offset
                transform.localPosition += data.positionOffset;

                // Apply scale offset
                transform.localScale = Vector3.Scale(transform.localScale, data.scaleOffset);
            }

            // Apply render settings from EnemyManager (passed as parameters)
            if (hoverSpriteOverride != null)
            {
                hoverSprite = hoverSpriteOverride;
            }

            if (hoverSpriteYOffsetOverride.HasValue)
            {
                hoverSpriteYOffset = hoverSpriteYOffsetOverride.Value;

                // Update hover sprite position with new Y offset
                if (hoverSpriteRoot != null)
                {
                    hoverSpriteRoot.transform.localPosition = new Vector3(0f, hoverSpriteYOffset, 0f);
                }
            }

            if (intentIconOffsetOverride.HasValue)
            {
                intentIconOffset = intentIconOffsetOverride.Value;

                // Update intent icon object with new settings
                if (intentIconRoot != null)
                {
                    intentIconRoot.transform.localPosition = intentIconOffset;
                }
            }

            if (intentIconSizeOverride.HasValue)
            {
                intentIconSize = intentIconSizeOverride.Value;

                // Update intent icon object with new settings
                if (intentIconRoot != null)
                {
                    intentIconRoot.transform.localScale = Vector3.one * intentIconSize;
                }
            }

            if (hoverSpriteSortingOrderOffsetOverride.HasValue)
            {
                hoverSpriteSortingOrderOffset = hoverSpriteSortingOrderOffsetOverride.Value;

                // Update hover sprite sorting order
                if (hoverSpriteRenderer != null)
                {
                    hoverSpriteRenderer.sortingOrder = _sprite.sortingOrder + hoverSpriteSortingOrderOffset;
                }
            }

            _health = GetComponentInChildren<EnemyHealth>();

            _hitboxCollider.offset = new Vector2(0f, 0.05f);
            _hitboxCollider.size = new Vector2(0.3f, 0.3f);

            // Update health display
            UpdateHealth();

            // Update intent icon
            UpdateIntentIcon();

            PlayIdle();
        }

        /// <summary>
        /// Updates the intent icon based on the current enemy data intent.
        /// Call this after rolling intents or when intent changes.
        /// </summary>
        public void UpdateIntentIcon(GameItems.Cards.CardIconLibrary iconLibrary = null)
        {
            if (data == null || intentIconSprite == null)
            {
                HideIntentIcon();
                return;
            }

            // If no icon library provided, try to load default one
            if (iconLibrary == null)
            {
                iconLibrary = UnityEngine.Resources.Load<GameItems.Cards.CardIconLibrary>("Nether/StatusIcons/DefaultCardIconLibrary");
            }

            if (iconLibrary == null)
            {
                Debug.LogWarning($"[EnemyRender] No icon library available for {data.enemyName}");
                HideIntentIcon();
                return;
            }

            Sprite intentSprite = iconLibrary.GetIconForIntent(data.currentIntent);

            if (intentSprite != null)
            {
                intentIconSprite.sprite = intentSprite;
                intentIconSprite.enabled = true;

                // Show intent value if > 0
                if (intentValueText != null && data.intentValue > 0)
                {
                    intentValueText.text = data.intentValue.ToString();
                    intentValueText.enabled = true;
                }
                else if (intentValueText != null)
                {
                    intentValueText.enabled = false;
                }
            }
            else
            {
                HideIntentIcon();
                Debug.LogWarning($"[EnemyRender] No intent icon for {data.enemyName} with intent {data.currentIntent}");
            }
        }

        /// <summary>
        /// Hides the intent icon (e.g., when enemy is dead or has no intent).
        /// </summary>
        public void HideIntentIcon()
        {
            if (intentIconSprite != null)
            {
                intentIconSprite.enabled = false;
            }

            if (intentValueText != null)
            {
                intentValueText.enabled = false;
            }
        }

        /// <summary>
        /// Shows the intent icon with the given sprite.
        /// </summary>
        public void ShowIntentIcon(Sprite icon)
        {
            if (intentIconSprite != null && icon != null)
            {
                intentIconSprite.sprite = icon;
                intentIconSprite.enabled = true;
            }
        }

        /// <summary>
        /// Shows a popup text with the move name that floats up and fades out.
        /// Call this immediately before the enemy executes their action.
        /// </summary>
        /// <param name="moveName">The name of the move to display</param>
        /// <param name="onComplete">Optional callback when animation completes</param>
        public void ShowMoveNamePopup(string moveName, System.Action onComplete = null)
        {
            if (moveNameText == null || string.IsNullOrEmpty(moveName))
            {
                onComplete?.Invoke();
                return;
            }

            // Play sound effect if assigned
            if (moveNameSoundCue != null && SFXManager.Instance != null)
            {
                SFXManager.Instance.Play(moveNameSoundCue);
            }

            // Set the move name text
            moveNameText.text = moveName.ToUpper();
            moveNameText.enabled = true;

            // Reset position and alpha
            if (moveNameRoot != null)
            {
                moveNameRoot.transform.localPosition = moveNameOffset;
            }
            moveNameText.alpha = 1f;

            // Kill any existing tweens on this object
            if (moveNameRoot != null)
            {
                DOTween.Kill(moveNameRoot.transform);
            }
            DOTween.Kill(moveNameText);

            // Create animation sequence
            Sequence moveSequence = DOTween.Sequence();

            if (moveNameRoot != null)
            {
                // Float up
                moveSequence.Append(moveNameRoot.transform
                    .DOLocalMoveY(moveNameOffset.y + moveNameFloatDistance, moveNameDuration)
                    .SetEase(Ease.OutCubic));
            }

            // Fade out in the last half of the animation
            moveSequence.Join(moveNameText
                .DOFade(0f, moveNameDuration * 0.5f)
                .SetDelay(moveNameDuration * 0.5f));

            // Hide and callback when complete
            moveSequence.OnComplete(() =>
            {
                if (moveNameText != null)
                    moveNameText.enabled = false;
                onComplete?.Invoke();
            });
        }

        /// <summary>
        /// Gets the move name for the given action.
        /// Returns custom name if set, otherwise returns default name based on intent.
        /// </summary>
        public string GetMoveNameForAction(EnemyAction action)
        {
            // Check if custom name is set
            if (!string.IsNullOrEmpty(action.customName))
            {
                return action.customName;
            }

            // Return default name based on intent
            return action.intent switch
            {
                EnemyIntent.Attack => "Attack",
                EnemyIntent.Block => "Defend",
                EnemyIntent.Heal => "Heal",
                EnemyIntent.Buff => "Buff",
                _ => "???"
            };
        }

        /// <summary>
        /// Gets the move name based on the current intent (legacy method).
        /// Use GetMoveNameForAction() for custom name support.
        /// </summary>
        public string GetMoveNameForIntent(EnemyIntent intent)
        {
            return intent switch
            {
                EnemyIntent.Attack => "Attack",
                EnemyIntent.Block => "Defend",
                EnemyIntent.Heal => "Heal",
                EnemyIntent.Buff => "Buff",
                _ => "???"
            };
        }

        public void UpdateHealth()
        {
            if (_health != null && data != null)
            {
                _health.SetHealth(data.currentHealth, data.maxHealth);
                _health.SetShield(data.block);
            }
        }

        public void PlayIdle()
        {
            if (data != null && data.idleAnim != null)
                PlayAnimation(data.idleAnim);
        }

        public void PlayAttack()
        {
            if (data != null && data.attackAnim != null)
                PlayAnimation(data.attackAnim);
        }

        public void PlayHurt()
        {
            if (data != null && data.hurtAnim != null)
                PlayAnimation(data.hurtAnim);
        }

        public void PlayDeath()
        {
            // Hide intent icon on death
            HideIntentIcon();

            // if (data != null && data.deathAnim != null)
            // {
            //     PlayAnimation(data.deathAnim);
            // }
            // else
            // {
            //     // Hide on death if no clip
            //     if (_sprite != null) _sprite.enabled = false;
            // }

            // run death through coroutine
            if (data != null && data.deathAnim != null)
            {
                StartCoroutine(PlayDeathThenDestroy());
            }
            else
            {
                Destroy(gameObject);
            }
        }

        private void PlayAnimation(SpriteAnimation anim)
        {
            if (anim == null || anim.frames.Count == 0)
            {
                _isAnimationPlaying = false;
                return;
            }

            _currentAnimation = anim;
            _isAnimationPlaying = true;
            _currentFrame = 0;
            _frameTimer = 0f;

            // Set the first frame immediately
            _sprite.sprite = _currentAnimation.frames[0];
        }


        private System.Collections.IEnumerator PlayDeathThenDestroy()
        {
            // play the manual sprite animation
            PlayAnimation(data.deathAnim);

            // wait for death animation duration
            float duration = data.deathAnim.Duration;
            if (duration <= 0) duration = 0.5f;

            yield return new WaitForSeconds(duration);

            Destroy(gameObject);
        }

        // Remove all the old Playables and Animator-related methods
        // ... (CrossFadeState, HasState, PlayClip, ReturnToIdleAfterClip, EnsureGraph, StopGraph)


        /// <summary>
        /// Shows the hover sprite overlay on the enemy.
        /// </summary>
        public void ShowHoverSprite()
        {
            if (hoverSpriteRenderer != null && hoverSprite != null)
            {
                // Only start animation if sprite wasn't already visible
                bool wasAlreadyVisible = hoverSpriteRenderer.enabled;

                hoverSpriteRenderer.sprite = hoverSprite;
                hoverSpriteRenderer.enabled = true;

                // Start pulse animation only if this is a new show (not already visible)
                if (!wasAlreadyVisible)
                {
                    StartHoverSpritePulseAnimation();
                }
            }
        }

        /// <summary>
        /// Hides the hover sprite overlay from the enemy.
        /// </summary>
        public void HideHoverSprite()
        {
            if (hoverSpriteRenderer != null)
            {
                hoverSpriteRenderer.enabled = false;
            }

            // Stop pulse animation
            StopHoverSpritePulseAnimation();
        }

        /// <summary>
        /// Starts the looping pulse animation for the hover sprite.
        /// </summary>
        private void StartHoverSpritePulseAnimation()
        {
            if (hoverSpriteRoot == null)
                return;

            // Stop any existing pulse tween
            StopHoverSpritePulseAnimation();

            // Create a looping sequence that expands then contracts
            Sequence pulseSequence = DOTween.Sequence();

            // Expand to max scale (first half of pulse)
            pulseSequence.Append(
                hoverSpriteRoot.transform
                    .DOScale(Vector3.one * hoverSpriteMaxScale, hoverSpritePulseDuration * 0.5f)
                    .SetEase(Ease.InOutSine)
            );

            // Contract back to normal scale (second half of pulse)
            pulseSequence.Append(
                hoverSpriteRoot.transform
                    .DOScale(Vector3.one, hoverSpritePulseDuration * 0.5f)
                    .SetEase(Ease.InOutSine)
            );

            // Loop forever
            pulseSequence.SetLoops(-1, LoopType.Restart);

            // Store reference so we can kill it later
            _hoverSpritePulseTween = pulseSequence;
        }

        /// <summary>
        /// Stops the hover sprite pulse animation.
        /// </summary>
        private void StopHoverSpritePulseAnimation()
        {
            if (_hoverSpritePulseTween != null)
            {
                _hoverSpritePulseTween.Kill();
                _hoverSpritePulseTween = null;
            }

            // Reset scale to normal
            if (hoverSpriteRoot != null)
            {
                hoverSpriteRoot.transform.localScale = Vector3.one;
            }
        }
    }
}

using Entities.Enemies.Helpers;
using UnityEngine;
using TMPro;
using DG.Tweening;
using GameItems.Cards;

namespace Entities.Enemies.Render
{
    [RequireComponent(typeof(Animator))]
    [RequireComponent(typeof(SpriteRenderer))]
    [RequireComponent(typeof(BoxCollider2D))]
    public class EnemyRender : MonoBehaviour
    {
        [Header("Runtime")] public EnemyData data;

        [Header("Intent Icon")]
        [Tooltip("Offset from enemy position where intent icon appears")]
        public Vector3 intentIconOffset = new Vector3(0f, 0.23f, 0f);
        [Tooltip("Size of the intent icon sprite")]
        public float intentIconSize = 0.2f;
        [Tooltip("Sorting layer for intent icon")]
        public string intentIconSortingLayer = "Default";
        [Tooltip("Sorting order offset from enemy sprite")]
        public int intentIconSortingOrderOffset = 10;

        [Header("Intent Value Text")]
        [Tooltip("Offset from icon where value text appears")]
        public Vector3 intentValueOffset = new(0.15f, -0.12f, 0f);
        [Tooltip("Font size for intent value")]
        public float intentValueFontSize = 2f;
        [Tooltip("Color for intent value text")]
        public Color intentValueColor = Color.white;

        [Header("Move Name Popup")]
        [Tooltip("Offset from enemy position where move name appears")]
        public Vector3 moveNameOffset = new(0f, -0.11f, 0f);
        [Tooltip("Font size for move name")]
        public float moveNameFontSize = 2f;
        [Tooltip("Color for move name text")]
        public Color moveNameColor = Color.yellow;
        [Tooltip("Duration of move name popup animation")]
        public float moveNameDuration = 1.5f;
        [Tooltip("How far the text moves up during animation")]
        public float moveNameFloatDistance = -0.04f;
        [Tooltip("Sound effect to play when move name appears")]
        public SFXCueData moveNameSoundCue;

        [Header("Enemy Action Sounds")]
        [Tooltip("Sound effect to play when enemy attacks")]
        public SFXCueData enemyAttackSoundCue;
        [Tooltip("Sound effect to play when enemy gains block/defends")]
        public SFXCueData enemyDefenseSoundCue;

        [Header("Hover Sprite")]
        [Tooltip("Sprite to show when enemy is hovered over")]
        public Sprite hoverSprite;
        [Tooltip("Y offset for hover sprite position")]
        public float hoverSpriteYOffset;
        [Tooltip("Sorting layer for hover sprite")]
        public string hoverSpriteSortingLayer = "Default";
        [Tooltip("Sorting order offset from enemy sprite")]
        public int hoverSpriteSortingOrderOffset = 5;

        [Header("Hover Sprite Animation")]
        [Tooltip("Maximum scale multiplier when hover sprite expands")]
        public float hoverSpriteMaxScale = 1.1f;
        [Tooltip("Duration of one pulse cycle (expand + contract)")]
        public float hoverSpritePulseDuration = 1f;

        [Header("Animator States (Controller-driven)")]
        public string idleState = "Idle";

        public string attackState = "Attack";
        public string hurtState = "Hurt";
        public string deathState = "Death";
        public int animatorLayer;
        public float crossFadeDuration = 0.08f;

        // References provided by EnemyPrefab hierarchy
        [Header("Prefab References")]
        [Tooltip("Root GameObject for the intent icon (child of EnemyPrefab)")]
        [SerializeField] private GameObject intentIconRoot;
        [Tooltip("SpriteRenderer used for the intent icon")] 
        [SerializeField] private SpriteRenderer intentIconSprite;
        [Tooltip("TextMeshPro component used for the intent value")] 
        [SerializeField] private TMP_Text intentValueText;
        [Tooltip("Root GameObject for the move name popup text")] 
        [SerializeField] private GameObject moveNameRoot;
        [Tooltip("TextMeshPro component used for the move name popup")] 
        [SerializeField] private TMP_Text moveNameText;
        [Tooltip("Root GameObject for the hover sprite")] 
        [SerializeField] private GameObject hoverSpriteRoot;
        [Tooltip("SpriteRenderer used for the hover overlay")] 
        [SerializeField] private SpriteRenderer hoverSpriteRenderer;

        private SpriteRenderer _sprite;
        private EnemyHealth _health;
        private BoxCollider2D _hitboxCollider;

        private Tween _hoverSpritePulseTween; // Tracks the pulse animation

        // Manual sprite animation state
        private SpriteAnimation _currentAnimation;
        private float _frameTimer;
        private int _currentFrame;
        private bool _isAnimationPlaying;

        private void Awake()
        {
            _hitboxCollider = GetComponent<BoxCollider2D>();
            _sprite = GetComponent<SpriteRenderer>();

            // Apply initial offsets/sizing to prefab children if they are assigned
            if (intentIconRoot != null)
            {
                intentIconRoot.transform.localPosition = intentIconOffset;
                intentIconRoot.transform.localScale = Vector3.one * intentIconSize;
            }
            if (intentIconSprite != null)
            {
                intentIconSprite.sortingLayerName = intentIconSortingLayer;
                intentIconSprite.sortingOrder = _sprite.sortingOrder + intentIconSortingOrderOffset;
                intentIconSprite.enabled = false;
            }
            if (intentValueText != null)
            {
                intentValueText.rectTransform.localPosition = intentValueOffset;
                intentValueText.fontSize = intentValueFontSize;
                intentValueText.color = intentValueColor;
                intentValueText.alignment = TextAlignmentOptions.Center;
                intentValueText.enabled = false;
            }

            if (moveNameRoot != null)
            {
                moveNameRoot.transform.localPosition = moveNameOffset;
            }
            if (moveNameText != null)
            {
                moveNameText.fontSize = moveNameFontSize;
                moveNameText.color = moveNameColor;
                moveNameText.alignment = TextAlignmentOptions.Center;
                moveNameText.fontStyle = FontStyles.Bold;
                moveNameText.enabled = false;
            }

            if (hoverSpriteRoot != null)
            {
                hoverSpriteRoot.transform.localPosition = new Vector3(0f, hoverSpriteYOffset, 0f);
            }
            if (hoverSpriteRenderer != null)
            {
                hoverSpriteRenderer.sortingLayerName = hoverSpriteSortingLayer;
                hoverSpriteRenderer.sortingOrder = _sprite.sortingOrder + hoverSpriteSortingOrderOffset;
                if (hoverSpriteRenderer.color.a == 0f)
                {
                    hoverSpriteRenderer.color = new Color32(251, 236, 93, 150);
                }
                hoverSpriteRenderer.enabled = false;
            }
        }

        private void Update()
        {
            if (!_isAnimationPlaying || _currentAnimation == null || _currentAnimation.frames.Count == 0)
                return;

            _frameTimer += Time.deltaTime;
            float frameDuration = 1f / _currentAnimation.frameRate;

            if (_frameTimer >= frameDuration)
            {
                _frameTimer -= frameDuration;
                _currentFrame++;

                if (_currentFrame >= _currentAnimation.frames.Count)
                {
                    if (_currentAnimation.loop)
                    {
                        _currentFrame = 0;
                    }
                    else
                    {
                        _isAnimationPlaying = false;
                        PlayIdle(); // Revert to idle when non-looping animation finishes
                        return;
                    }
                }

                _sprite.sprite = _currentAnimation.frames[_currentFrame];
            }
            data.worldPosition = transform.position;
        }


        public void Bind(EnemyData enemyData, Sprite hoverSpriteOverride = null, float? hoverSpriteYOffsetOverride = null, Vector3? intentIconOffsetOverride = null, float? intentIconSizeOverride = null, int? hoverSpriteSortingOrderOffsetOverride = null)
        {
            data = enemyData;
            data.worldPosition = transform.position;
            data.isPlayer = false;

            // Set default sprite artwork
            if (_sprite != null)
            {
                _sprite.sprite = data != null ? data.artwork : null;
                _sprite.enabled = _sprite.sprite != null;
            }

            // Apply visual adjustments from EnemyData
            if (data != null)
            {
                // Apply position offset
                transform.localPosition += data.positionOffset;

                // Apply scale offset
                transform.localScale = Vector3.Scale(transform.localScale, data.scaleOffset);
            }

            // Apply render settings from EnemyManager (passed as parameters)
            if (hoverSpriteOverride != null)
            {
                hoverSprite = hoverSpriteOverride;
            }

            if (hoverSpriteYOffsetOverride.HasValue)
            {
                hoverSpriteYOffset = hoverSpriteYOffsetOverride.Value;

                // Update hover sprite position with new Y offset
                if (hoverSpriteRoot != null)
                {
                    hoverSpriteRoot.transform.localPosition = new Vector3(0f, hoverSpriteYOffset, 0f);
                }
            }

            if (intentIconOffsetOverride.HasValue)
            {
                intentIconOffset = intentIconOffsetOverride.Value;

                // Update intent icon object with new settings
                if (intentIconRoot != null)
                {
                    intentIconRoot.transform.localPosition = intentIconOffset;
                }
            }

            if (intentIconSizeOverride.HasValue)
            {
                intentIconSize = intentIconSizeOverride.Value;

                // Update intent icon object with new settings
                if (intentIconRoot != null)
                {
                    intentIconRoot.transform.localScale = Vector3.one * intentIconSize;
                }
            }

            if (hoverSpriteSortingOrderOffsetOverride.HasValue)
            {
                hoverSpriteSortingOrderOffset = hoverSpriteSortingOrderOffsetOverride.Value;

                // Update hover sprite sorting order
                if (hoverSpriteRenderer != null)
                {
                    hoverSpriteRenderer.sortingOrder = _sprite.sortingOrder + hoverSpriteSortingOrderOffset;
                }
            }

            _health = GetComponentInChildren<EnemyHealth>();

            _hitboxCollider.offset = new Vector2(0f, 0.05f);
            _hitboxCollider.size = new Vector2(0.3f, 0.3f);

            // Update health display
            UpdateHealth();

            // Update intent icon
            UpdateIntentIcon();

            PlayIdle();
        }

        /// <summary>
        /// Updates the intent icon based on the current enemy data intent.
        /// Call this after rolling intents or when intent changes.
        /// </summary>
        public void UpdateIntentIcon(GameItems.Cards.CardIconLibrary iconLibrary = null)
        {
            if (data == null || intentIconSprite == null)
            {
                HideIntentIcon();
                return;
            }

            // If no icon library provided, try to load default one
            if (iconLibrary == null)
            {
                iconLibrary = UnityEngine.Resources.Load<GameItems.Cards.CardIconLibrary>("Nether/StatusIcons/DefaultCardIconLibrary");
            }

            if (iconLibrary == null)
            {
                Debug.LogWarning($"[EnemyRender] No icon library available for {data.enemyName}");
                HideIntentIcon();
                return;
            }

            Sprite intentSprite = iconLibrary.GetIconForIntent(data.currentIntent);

            if (intentSprite != null)
            {
                intentIconSprite.sprite = intentSprite;
                intentIconSprite.enabled = true;

                // Show intent value if > 0
                if (intentValueText != null && data.intentValue > 0)
                {
                    intentValueText.text = data.intentValue.ToString();
                    intentValueText.enabled = true;
                }
                else if (intentValueText != null)
                {
                    intentValueText.enabled = false;
                }
            }
            else
            {
                HideIntentIcon();
                Debug.LogWarning($"[EnemyRender] No intent icon for {data.enemyName} with intent {data.currentIntent}");
            }
        }

        /// <summary>
        /// Hides the intent icon (e.g., when enemy is dead or has no intent).
        /// </summary>
        public void HideIntentIcon()
        {
            if (intentIconSprite != null)
            {
                intentIconSprite.enabled = false;
            }

            if (intentValueText != null)
            {
                intentValueText.enabled = false;
            }
        }

        /// <summary>
        /// Shows the intent icon with the given sprite.
        /// </summary>
        public void ShowIntentIcon(Sprite icon)
        {
            if (intentIconSprite != null && icon != null)
            {
                intentIconSprite.sprite = icon;
                intentIconSprite.enabled = true;
            }
        }

        /// <summary>
        /// Shows a popup text with the move name that floats up and fades out.
        /// Call this immediately before the enemy executes their action.
        /// </summary>
        /// <param name="moveName">The name of the move to display</param>
        /// <param name="onComplete">Optional callback when animation completes</param>
        public void ShowMoveNamePopup(string moveName, System.Action onComplete = null)
        {
            if (moveNameText == null || string.IsNullOrEmpty(moveName))
            {
                onComplete?.Invoke();
                return;
            }

            // Play sound effect if assigned
            if (moveNameSoundCue != null && SFXManager.Instance != null)
            {
                SFXManager.Instance.Play(moveNameSoundCue);
            }

            // Set the move name text
            moveNameText.text = moveName.ToUpper();
            moveNameText.enabled = true;

            // Reset position and alpha
            if (moveNameRoot != null)
            {
                moveNameRoot.transform.localPosition = moveNameOffset;
            }
            moveNameText.alpha = 1f;

            // Kill any existing tweens on this object
            if (moveNameRoot != null)
            {
                DOTween.Kill(moveNameRoot.transform);
            }
            DOTween.Kill(moveNameText);

            // Create animation sequence
            Sequence moveSequence = DOTween.Sequence();

            if (moveNameRoot != null)
            {
                // Float up
                moveSequence.Append(moveNameRoot.transform
                    .DOLocalMoveY(moveNameOffset.y + moveNameFloatDistance, moveNameDuration)
                    .SetEase(Ease.OutCubic));
            }

            // Fade out in the last half of the animation
            moveSequence.Join(moveNameText
                .DOFade(0f, moveNameDuration * 0.5f)
                .SetDelay(moveNameDuration * 0.5f));

            // Hide and callback when complete
            moveSequence.OnComplete(() =>
            {
                if (moveNameText != null)
                    moveNameText.enabled = false;
                onComplete?.Invoke();
            });
        }

        /// <summary>
        /// Gets the move name for the given action.
        /// Returns custom name if set, otherwise returns default name based on intent.
        /// </summary>
        public string GetMoveNameForAction(EnemyAction action)
        {
            // Check if custom name is set
            if (!string.IsNullOrEmpty(action.customName))
            {
                return action.customName;
            }

            // Return default name based on intent
            return action.intent switch
            {
                EnemyIntent.Attack => "Attack",
                EnemyIntent.Block => "Defend",
                EnemyIntent.Heal => "Heal",
                EnemyIntent.Buff => "Buff",
                _ => "???"
            };
        }

        /// <summary>
        /// Gets the move name based on the current intent (legacy method).
        /// Use GetMoveNameForAction() for custom name support.
        /// </summary>
        public string GetMoveNameForIntent(EnemyIntent intent)
        {
            return intent switch
            {
                EnemyIntent.Attack => "Attack",
                EnemyIntent.Block => "Defend",
                EnemyIntent.Heal => "Heal",
                EnemyIntent.Buff => "Buff",
                _ => "???"
            };
        }

        /// <summary>
        /// Plays the enemy attack sound effect.
        /// Call this when the enemy is about to execute an attack action.
        /// </summary>
        public void PlayEnemyAttackSound()
        {
            Debug.Log($"[EnemyRender] PlayEnemyAttackSound called for {data?.enemyName ?? "unknown"}. AttackCue assigned: {enemyAttackSoundCue != null}, SFXManager: {SFXManager.Instance != null}");

            if (enemyAttackSoundCue != null && SFXManager.Instance != null)
            {
                Debug.Log($"[EnemyRender] Playing enemy attack sound: {enemyAttackSoundCue.cueName}");
                SFXManager.Instance.Play(enemyAttackSoundCue);
            }
            else if (enemyAttackSoundCue == null)
            {
                Debug.LogWarning($"[EnemyRender] Enemy attack sound cue not assigned for {data?.enemyName ?? "unknown"}");
            }
        }

        /// <summary>
        /// Plays the enemy defense sound effect.
        /// Call this when the enemy is about to execute a block/defense action.
        /// </summary>
        public void PlayEnemyDefenseSound()
        {
            Debug.Log($"[EnemyRender] PlayEnemyDefenseSound called for {data?.enemyName ?? "unknown"}. DefenseCue assigned: {enemyDefenseSoundCue != null}, SFXManager: {SFXManager.Instance != null}");

            if (enemyDefenseSoundCue != null && SFXManager.Instance != null)
            {
                Debug.Log($"[EnemyRender] Playing enemy defense sound: {enemyDefenseSoundCue.cueName}");
                SFXManager.Instance.Play(enemyDefenseSoundCue);
            }
            else if (enemyDefenseSoundCue == null)
            {
                Debug.LogWarning($"[EnemyRender] Enemy defense sound cue not assigned for {data?.enemyName ?? "unknown"}");
            }
        }

        public void UpdateHealth()
        {
            if (_health != null && data != null)
            {
                _health.SetHealth(data.currentHealth, data.maxHealth);
                _health.SetShield(data.block);
            }
        }

        public void PlayIdle()
        {
            if (data != null && data.idleAnim != null)
                PlayAnimation(data.idleAnim);
        }

        public void PlayAttack()
        {
            if (data != null && data.attackAnim != null)
                PlayAnimation(data.attackAnim);
        }

        public void PlayHurt()
        {
            if (data != null && data.hurtAnim != null)
                PlayAnimation(data.hurtAnim);
        }

        public void PlayDeath()
        {
            // Hide intent icon on death
            HideIntentIcon();

            // if (data != null && data.deathAnim != null)
            // {
            //     PlayAnimation(data.deathAnim);
            // }
            // else
            // {
            //     // Hide on death if no clip
            //     if (_sprite != null) _sprite.enabled = false;
            // }

            // run death through coroutine
            if (data != null && data.deathAnim != null)
            {
                StartCoroutine(PlayDeathThenDestroy());
            }
            else
            {
                Destroy(gameObject);
            }
        }

        private void PlayAnimation(SpriteAnimation anim)
        {
            if (anim == null || anim.frames.Count == 0)
            {
                _isAnimationPlaying = false;
                return;
            }

            _currentAnimation = anim;
            _isAnimationPlaying = true;
            _currentFrame = 0;
            _frameTimer = 0f;

            // Set the first frame immediately
            _sprite.sprite = _currentAnimation.frames[0];
        }


        private System.Collections.IEnumerator PlayDeathThenDestroy()
        {
            // play the manual sprite animation
            PlayAnimation(data.deathAnim);

            // wait for death animation duration
            float duration = data.deathAnim.Duration;
            if (duration <= 0) duration = 0.5f;

            yield return new WaitForSeconds(duration);

            Destroy(gameObject);
        }

        // Remove all the old Playables and Animator-related methods
        // ... (CrossFadeState, HasState, PlayClip, ReturnToIdleAfterClip, EnsureGraph, StopGraph)


        /// <summary>
        /// Shows the hover sprite overlay on the enemy.
        /// </summary>
        public void ShowHoverSprite()
        {
            if (hoverSpriteRenderer != null && hoverSprite != null)
            {
                // Only start animation if sprite wasn't already visible
                bool wasAlreadyVisible = hoverSpriteRenderer.enabled;

                hoverSpriteRenderer.sprite = hoverSprite;
                hoverSpriteRenderer.enabled = true;

                // Start pulse animation only if this is a new show (not already visible)
                if (!wasAlreadyVisible)
                {
                    StartHoverSpritePulseAnimation();
                }
            }
        }

        /// <summary>
        /// Hides the hover sprite overlay from the enemy.
        /// </summary>
        public void HideHoverSprite()
        {
            if (hoverSpriteRenderer != null)
            {
                hoverSpriteRenderer.enabled = false;
            }

            // Stop pulse animation
            StopHoverSpritePulseAnimation();
        }

        /// <summary>
        /// Starts the looping pulse animation for the hover sprite.
        /// </summary>
        private void StartHoverSpritePulseAnimation()
        {
            if (hoverSpriteRoot == null)
                return;

            // Stop any existing pulse tween
            StopHoverSpritePulseAnimation();

            // Create a looping sequence that expands then contracts
            Sequence pulseSequence = DOTween.Sequence();

            // Expand to max scale (first half of pulse)
            pulseSequence.Append(
                hoverSpriteRoot.transform
                    .DOScale(Vector3.one * hoverSpriteMaxScale, hoverSpritePulseDuration * 0.5f)
                    .SetEase(Ease.InOutSine)
            );

            // Contract back to normal scale (second half of pulse)
            pulseSequence.Append(
                hoverSpriteRoot.transform
                    .DOScale(Vector3.one, hoverSpritePulseDuration * 0.5f)
                    .SetEase(Ease.InOutSine)
            );

            // Loop forever
            pulseSequence.SetLoops(-1, LoopType.Restart);

            // Store reference so we can kill it later
            _hoverSpritePulseTween = pulseSequence;
        }

        /// <summary>
        /// Stops the hover sprite pulse animation.
        /// </summary>
        private void StopHoverSpritePulseAnimation()
        {
            if (_hoverSpritePulseTween != null)
            {
                _hoverSpritePulseTween.Kill();
                _hoverSpritePulseTween = null;
            }

            // Reset scale to normal
            if (hoverSpriteRoot != null)
            {
                hoverSpriteRoot.transform.localScale = Vector3.one;
            }
        }
    }
}

using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace GameItems
{
    /// <summary>
    /// Displays the turn timer UI with a countdown and optional visual feedback.
    /// </summary>
    public class TurnTimerUI : MonoBehaviour
    {
        [Header("References")]
        [Tooltip("Reference to the RoundManager to read timer values")]
        public RoundManager roundManager;

        [Header("UI Elements")]
        [Tooltip("Text component to display the remaining time")]
        public TextMeshProUGUI timerText;

        [Tooltip("Optional fill image to show timer visually")]
        public Image timerFillImage;

        [Header("Visual Settings")]
        [Tooltip("Color when time is plentiful")]
        public Color normalColor = Color.white;

        [Tooltip("Color when time is running low")]
        public Color warningColor = Color.yellow;

        [Tooltip("Color when time is almost out")]
        public Color criticalColor = Color.red;

        [Tooltip("Time threshold for warning color (seconds)")]
        public float warningThreshold = 7f;

        [Tooltip("Time threshold for critical color (seconds)")]
        public float criticalThreshold = 3f;

        private void Start()
        {
            // Auto-find RoundManager if not assigned
            if (roundManager == null)
            {
                roundManager = FindFirstObjectByType<RoundManager>();
            }

            if (roundManager == null)
            {
                Debug.LogError("TurnTimerUI: RoundManager not found!");
                enabled = false;
            }
        }

        private void Update()
        {
            if (roundManager == null || !roundManager.playerTurn || !roundManager.battleActive)
            {
                // Hide timer when not player's turn
                if (timerText != null) timerText.text = "";
                if (timerFillImage != null) timerFillImage.fillAmount = 0f;
                return;
            }

            float timeRemaining = roundManager.currentTurnTime;
            float timeLimit = roundManager.turnTimeLimit;

            // Update text
            if (timerText != null)
            {
                timerText.text = $"{Mathf.CeilToInt(timeRemaining)}s";

                // Update color based on time remaining
                if (timeRemaining <= criticalThreshold)
                {
                    timerText.color = criticalColor;
                }
                else if (timeRemaining <= warningThreshold)
                {
                    timerText.color = warningColor;
                }
                else
                {
                    timerText.color = normalColor;
                }
            }

            // Update fill image
            if (timerFillImage != null && timeLimit > 0)
            {
                timerFillImage.fillAmount = timeRemaining / timeLimit;

                // Update fill color
                if (timeRemaining <= criticalThreshold)
                {
                    timerFillImage.color = criticalColor;
                }
                else if (timeRemaining <= warningThreshold)
                {
                    timerFillImage.color = warningColor;
                }
                else
                {
                    timerFillImage.color = normalColor;
                }
            }
        }
    }
}
